const MG_INSTRUCTOR_LINE='You hold the flame steady, and those who approach decide whether to trust you.';
const MG={active:false,shown_tip:false,t:0,flame:50,target:50,target_drift:0,nomads:[],won:false,failed:false,dim_alpha:0,entry_done:false};
function mgInit(st=MG){st.active=false;st.shown_tip=false;st.t=0;st.flame=50;st.target=50;st.target_drift=0;st.nomads=[];for(let i=0;i<8;i++){const a=i*Math.PI/4;st.nomads.push({a:a,r:180,committed:true});}st.won=false;st.failed=false;st.dim_alpha=0;st.entry_done=false;}
function mgStep(st,clicked,dt){if(st.won||st.failed)return st;st.t+=dt;if(clicked)st.flame=Math.min(100,st.flame+18);st.flame=Math.max(0,st.flame-dt*1.8);st.target_drift+=dt*0.015;st.target=50+Math.sin(st.target_drift)*8;const inBand=Math.abs(st.flame-st.target)<=12;let allIn=true,anyOut=false;for(const n of st.nomads){if(inBand&&n.committed)n.r=Math.max(30,n.r-dt*0.35);else if(!inBand){n.committed=false;anyOut=true;}if(n.r>35)allIn=false;}if(st.flame>85){st.failed=true;return st;}if(st.flame<15){st.failed=true;return st;}if(allIn&&st.t>1000){st.won=true;}return st;}
if(location.hash.includes('mg')){const _ogNG=newGame;newGame=function(p){_ogNG(p);MG.active=true;mgInit(MG);MG.active=true;};}
